import heapq

def match(orders):
    orders_info = {}  # id -> {'side','qty','active'}
    buy_heap = []  # tuples (-price, seq, id)
    sell_heap = []  # tuples (price, seq, id)
    seq_counter = 0

    trades_out = []

    def try_match(side, price, qty, oid_incoming, is_market):
        nonlocal trades_out
        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while qty > 0 and heap:
            top = heap[0]
            if side == 'buy':
                p = top[0]
            else:
                p = -top[0]
            resting_id = top[2]
            info = orders_info.get(resting_id)
            if info is None or not info['active'] or info['qty'] == 0:
                heapq.heappop(heap)
                continue

            if not is_market:
                if side == 'buy' and price < p:
                    break
                if side == 'sell' and price > p:
                    break

            trade_qty = min(qty, info['qty'])
            if side == 'buy':
                buy_id, sell_id = oid_incoming, resting_id
            else:
                buy_id, sell_id = resting_id, oid_incoming

            trades_out.append([buy_id, sell_id, p, trade_qty])

            qty -= trade_qty
            info['qty'] -= trade_qty

            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(heap)
            else:
                # partial fill, keep its place in heap (do not pop)
                break_needed = False
                # since top qty >0, and incoming qty might still be >0, but resting order is now
                # smaller qty but still at same price, so if incoming qty still >0, it means
                # trade_qty == qty (incoming exhausted) since resting had more.
                # loop will exit due to qty==0 anyway.
                pass

        return qty

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1

        orders_info[oid] = {'side': side, 'qty': qty, 'active': True}

        is_market = (typ == 'market')

        remaining = try_match(side, price, qty, oid, is_market)

        orders_info[oid]['qty'] = remaining

        if typ == 'limit':
            if remaining > 0:
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq, oid))
            else:
                orders_info[oid]['active'] = False
        else:
            # ioc or market: discard remainder
            orders_info[oid]['active'] = False

    return trades_out

